4	// MARK: - Snapshot decoding errors
5	
6	struct SnapshotDecodeError: Error {
7	    let message: String
8	}
9	
10	// MARK: - Minimal strict JSON parser
11	//
12	// JSONSerialization is not strict enough for snapshot validation (it accepts
13	// duplicate keys, non-string fragments, and trailing garbage in some modes),
14	// so the snapshot format is validated with this small grammar-faithful
15	// parser instead.
16	
17	enum JSONValue {
18	    case null
19	    case bool(Bool)
20	    case number(String)                    // raw lexeme; grammar already validated
21	    case string(String)
22	    case array([JSONValue])
23	    case object([(String, JSONValue)])     // preserves member order and duplicates
24	}
25	
26	private struct JSONParser {
27	    private let scalars: [Unicode.Scalar]
28	    private var index = 0
29	
30	    init(_ text: String) {
31	        self.scalars = Array(text.unicodeScalars)
32	    }
33	
34	    static func parse(_ text: String) throws -> JSONValue {
35	        var parser = JSONParser(text)
36	        let value = try parser.parseValue()
37	        parser.skipWhitespace()
38	        guard parser.atEnd else {
39	            throw SnapshotDecodeError(message: "trailing content after JSON value")
40	        }
41	        return value
42	    }
43	
44	    private var atEnd: Bool { index >= scalars.count }
45	    private var current: Unicode.Scalar { scalars[index] }
46	
47	    private mutating func skipWhitespace() {
48	        while index < scalars.count {
49	            switch scalars[index] {
50	            case " ", "\t", "\n", "\r":
51	                index += 1
52	            default:
53	                return
54	            }
55	        }
56	    }
57	
58	    private mutating func parseValue() throws -> JSONValue {
59	        skipWhitespace()
60	        if atEnd { throw SnapshotDecodeError(message: "unexpected end of input") }
61	        switch current {
62	        case "{": return .object(try parseObject())
63	        case "[": return .array(try parseArray())
64	        case "\"": return .string(try parseString())
65	        case "t", "f": return try parseBool()
66	        case "n":
67	            try consumeLiteral("null")
68	            return .null
69	        default:
70	            if current == "-" || ("0"..."9").contains(current) {
71	                return .number(try parseNumber())
72	            }
73	            throw SnapshotDecodeError(message: "unexpected character in JSON")
74	        }
75	    }
76	
77	    private mutating func consumeLiteral(_ literal: String) throws {
78	        for scalar in literal.unicodeScalars {
79	            guard index < scalars.count, scalars[index] == scalar else {
80	                throw SnapshotDecodeError(message: "invalid JSON literal")
81	            }
82	            index += 1
83	        }
84	    }
85	
86	    private mutating func parseBool() throws -> JSONValue {
87	        if current == "t" {
88	            try consumeLiteral("true")
89	            return .bool(true)
90	        }
91	        try consumeLiteral("false")
92	        return .bool(false)
93	    }
94	
95	    private mutating func parseObject() throws -> [(String, JSONValue)] {
96	        index += 1 // "{"
97	        var members: [(String, JSONValue)] = []
98	        skipWhitespace()
99	        if !atEnd, current == "}" {
100	            index += 1
101	            return members
102	        }
103	        while true {
104	            skipWhitespace()
105	            if atEnd || current != "\"" {
106	                throw SnapshotDecodeError(message: "expected string key in object")
107	            }
108	            let key = try parseString()
109	            skipWhitespace()
110	            if atEnd || current != ":" {
111	                throw SnapshotDecodeError(message: "expected ':' after object key")
112	            }
113	            index += 1
114	            let value = try parseValue()
115	            members.append((key, value))
116	            skipWhitespace()
117	            if atEnd { throw SnapshotDecodeError(message: "unterminated object") }
118	            switch current {
119	            case ",":
120	                index += 1
121	                skipWhitespace()
122	                if atEnd || current != "\"" {
123	                    throw SnapshotDecodeError(message: "trailing comma in object")
124	                }
125	            case "}":
126	                index += 1
127	                return members
128	            default:
129	                throw SnapshotDecodeError(message: "expected ',' or '}' in object")
130	            }
131	        }
132	    }
133	
134	    private mutating func parseArray() throws -> [JSONValue] {
135	        index += 1 // "["
136	        var items: [JSONValue] = []
137	        skipWhitespace()
138	        if !atEnd, current == "]" {
139	            index += 1
140	            return items
141	        }
142	        while true {
143	            try items.append(parseValue())
144	            skipWhitespace()
145	            if atEnd { throw SnapshotDecodeError(message: "unterminated array") }
146	            switch current {
147	            case ",":
148	                index += 1
149	                skipWhitespace()
150	                if atEnd || current == "]" {
151	                    throw SnapshotDecodeError(message: "trailing comma in array")
152	                }
153	            case "]":
154	                index += 1
155	                return items
156	            default:
157	                throw SnapshotDecodeError(message: "expected ',' or ']' in array")
158	            }
159	        }
160	    }
161	
162	    private mutating func parseString() throws -> String {
163	        index += 1 // opening quote
164	        var output = String.UnicodeScalarView()
165	        while index < scalars.count {
166	            let scalar = scalars[index]
167	            switch scalar {
168	            case "\"":
169	                index += 1
170	                return String(output)
171	            case "\\":
172	                index += 1
173	                if atEnd { throw SnapshotDecodeError(message: "unterminated escape sequence") }
174	                switch scalars[index] {
175	                case "\"": output.append("\""); index += 1
176	                case "\\": output.append("\\"); index += 1
177	                case "/": output.append("/"); index += 1
178	                case "b": output.append("\u{08}"); index += 1
179	                case "f": output.append("\u{0C}"); index += 1
180	                case "n": output.append("\n"); index += 1
181	                case "r": output.append("\r"); index += 1
182	                case "t": output.append("\t"); index += 1
183	                case "u":
184	                    let codepoint = try parseUnicodeEscape()
185	                    switch codepoint {
186	                    case 0xD800...0xDBFF:
187	                        // A high surrogate must be immediately followed by
188	                        // an escaped low surrogate; lone surrogates are invalid.
189	                        guard index + 1 < scalars.count,
190	                              scalars[index] == "\\", scalars[index + 1] == "u"
191	                        else {
192	                            throw SnapshotDecodeError(message: "lone high surrogate in string")
193	                        }
194	                        index += 1 // point at the second 'u'
195	                        let low = try parseUnicodeEscape()
196	                        guard (0xDC00...0xDFFF).contains(low) else {
197	                            throw SnapshotDecodeError(message: "invalid surrogate pair in string")
198	                        }
199	                        let combined = 0x10000
200	                            + ((codepoint - 0xD800) << 10)
201	                            + (low - 0xDC00)
202	                        output.append(Unicode.Scalar(combined)!)
203	                    case 0xDC00...0xDFFF:
204	                        throw SnapshotDecodeError(message: "lone low surrogate in string")
205	                    default:
206	                        guard let decoded = Unicode.Scalar(codepoint) else {
207	                            throw SnapshotDecodeError(message: "invalid unicode escape")
208	                        }
209	                        output.append(decoded)
210	                    }
211	                default:
212	                    throw SnapshotDecodeError(message: "invalid escape sequence")
213	                }
214	            case "\u{00}"..."\u{1F}":
215	                throw SnapshotDecodeError(message: "unescaped control character in string")
216	            default:
217	                output.append(scalar)
218	                index += 1
219	            }
220	        }
221	        throw SnapshotDecodeError(message: "unterminated string")
222	    }
223	
224	    /// Called with `index` pointing at the 'u' of a `\uXXXX` escape; leaves
225	    /// `index` right after the fourth hex digit.
226	    private mutating func parseUnicodeEscape() throws -> UInt32 {
227	        index += 1 // past 'u'
228	        guard index + 4 <= scalars.count else {
229	            throw SnapshotDecodeError(message: "incomplete unicode escape")
230	        }
231	        var value: UInt32 = 0
232	        for _ in 0..<4 {
233	            let scalar = scalars[index]
234	            let digit: UInt32
235	            switch scalar {
236	            case "0"..."9":
237	                digit = UInt32(scalar.value - Unicode.Scalar("0").value)
238	            case "a"..."f":
239	                digit = UInt32(scalar.value - Unicode.Scalar("a").value) + 10
240	            case "A"..."F":
241	                digit = UInt32(scalar.value - Unicode.Scalar("A").value) + 10
242	            default:
243	                throw SnapshotDecodeError(message: "invalid hex digit in unicode escape")
244	            }
245	            value = value * 16 + digit
246	            index += 1
247	        }
248	        return value
249	    }
250	
251	    private mutating func parseNumber() throws -> String {
252	        let start = index
253	        if current == "-" { index += 1 }
254	        guard index < scalars.count else {
255	            throw SnapshotDecodeError(message: "invalid number")
256	        }
257	        if scalars[index] == "0" {
258	            index += 1
259	        } else if ("1"..."9").contains(scalars[index]) {
260	            index += 1
261	            while index < scalars.count, ("0"..."9").contains(scalars[index]) { index += 1 }
262	        } else {
263	            throw SnapshotDecodeError(message: "invalid number")
264	        }
265	        if index < scalars.count, scalars[index] == "." {
266	            index += 1
267	            guard index < scalars.count, ("0"..."9").contains(scalars[index]) else {
268	                throw SnapshotDecodeError(message: "invalid number fraction")
269	            }
270	            while index < scalars.count, ("0"..."9").contains(scalars[index]) { index += 1 }
271	        }
272	        if index < scalars.count, scalars[index] == "e" || scalars[index] == "E" {
273	            index += 1
274	            if index < scalars.count, scalars[index] == "+" || scalars[index] == "-" { index += 1 }
275	            guard index < scalars.count, ("0"..."9").contains(scalars[index]) else {
276	                throw SnapshotDecodeError(message: "invalid number exponent")
277	            }
278	            while index < scalars.count, ("0"..."9").contains(scalars[index]) { index += 1 }
279	        }
280	        return String(String.UnicodeScalarView(scalars[start..<index]))
281	    }
282	}
