407	private func decodeFiles(_ value: JSONValue) throws -> [FileRecord] {
408	    guard case .array(let items) = value else {
409	        throw SnapshotDecodeError(message: "files must be an array")
410	    }
411	    var records: [FileRecord] = []
412	    var seenPaths = Set<Data>()
413	    var previousPath: String?
414	    for item in items {
415	        guard case .object(let members) = item else {
416	            throw SnapshotDecodeError(message: "each file entry must be an object")
417	        }
418	        let keys = Set(members.map { $0.0 })
419	        guard members.count == 3, keys == ["path", "sha256", "size"] else {
420	            throw SnapshotDecodeError(message: "file entry has missing or extra fields")
421	        }
422	        let fields = Dictionary(members, uniquingKeysWith: { $1 })
423	
424	        guard case .string(let path) = fields["path"], isValidRelativePath(path) else {
425	            throw SnapshotDecodeError(message: "file entry has an invalid path")
426	        }
427	        guard case .string(let sha256) = fields["sha256"], isValidSha256(sha256) else {
428	            throw SnapshotDecodeError(message: "file entry has an invalid sha256")
429	        }
430	        guard case .number(let sizeLexeme) = fields["size"],
431	              sizeLexeme.first != "-",
432	              let size = Int64(sizeLexeme, radix: 10), size >= 0
433	        else {
434	            throw SnapshotDecodeError(message: "file entry has an invalid size")
435	        }
436	
437	        let pathBytes = Data(path.utf8)
438	        if seenPaths.contains(pathBytes) {
439	            throw SnapshotDecodeError(message: "duplicate path in files: \(path)")
440	        }
441	        if let previous = previousPath, !utf8Precedes(previous, path) {
442	            throw SnapshotDecodeError(message: "file entries are not sorted by path")
443	        }
444	        seenPaths.insert(pathBytes)
445	        previousPath = path
446	        records.append(FileRecord(path: path, sha256: sha256, size: size))
447	    }
448	    return records
449	}
