451	/// Parses and strictly validates a snapshot, returning its file records.
452	/// Never repairs the file; any problem throws `SnapshotDecodeError`.
453	private func decodeSnapshot(_ data: Data) throws -> [FileRecord] {
454	    guard let text = String(data: data, encoding: .utf8) else {
455	        throw SnapshotDecodeError(message: "snapshot is not valid UTF-8")
456	    }
457	    let value = try JSONParser.parse(text)
458	    guard case .object(let members) = value else {
459	        throw SnapshotDecodeError(message: "snapshot root must be an object")
460	    }
461	    let keys = Set(members.map { $0.0 })
462	    guard members.count == 3, keys == ["version", "capturedAt", "files"] else {
463	        throw SnapshotDecodeError(message: "snapshot has missing or extra fields")
464	    }
465	    let fields = Dictionary(members, uniquingKeysWith: { $1 })
466	
467	    guard case .number(let versionLexeme) = fields["version"], versionLexeme == "1" else {
468	        throw SnapshotDecodeError(message: "unsupported snapshot version")
469	    }
470	    guard case .string(let capturedAt) = fields["capturedAt"], isValidTimestamp(capturedAt) else {
471	        throw SnapshotDecodeError(message: "invalid capturedAt timestamp")
472	    }
473	    return try decodeFiles(fields["files"]!)
474	}
