478	private func utcTimestamp() -> String {
479	    let formatter = DateFormatter()
480	    formatter.locale = Locale(identifier: "en_US_POSIX")
481	    formatter.timeZone = TimeZone(identifier: "UTC")
482	    formatter.dateFormat = "yyyy-MM-dd'T'HH:mm:ss'Z'"
483	    return formatter.string(from: Date())
484	}
