499	private func reportCollectionErrors(_ errors: [CompareError]) {
500	    let ordered = errors.enumerated().sorted { a, b in
501	        utf8Identical(a.element.path, b.element.path)
502	            ? a.offset < b.offset
503	            : utf8Precedes(a.element.path, b.element.path)
504	    }
505	    var text = ""
506	    for error in ordered {
507	        text += "error: \(error.element.path): \(error.element.message)\n"
508	    }
509	    writeStderr(text)
510	}
