580	// MARK: - `snapshot`
581	
582	func runSnapshot(sourcePath: String, snapshotPath: String) -> Int32 {
583	    let fileManager = FileManager.default
584	
585	    var sourceIsDirectory: ObjCBool = false
586	    guard fileManager.fileExists(atPath: sourcePath, isDirectory: &sourceIsDirectory),
587	          sourceIsDirectory.boolValue
588	    else {
589	        writeStderr("error: not an existing directory: \(sourcePath)\n")
590	        return 64
591	    }
592	
593	    let sourceRoot = normalizedRoot(sourcePath)
594	    let snapshotURL = URL(fileURLWithPath: snapshotPath)
595	    let resolvedParent = normalizedRoot(snapshotURL.deletingLastPathComponent().path)
596	    let resolvedSnapshot = (resolvedParent as NSString)
597	        .appendingPathComponent(snapshotURL.lastPathComponent)
598	    guard !isPath(resolvedSnapshot, inside: sourceRoot) else {
599	        writeStderr("error: SNAPSHOT must not be located inside SOURCE: \(snapshotPath)\n")
600	        return 64
601	    }
602	
603	    guard !fileManager.fileExists(atPath: snapshotPath) else {
604	        writeStderr("error: snapshot destination already exists: \(snapshotPath)\n")
605	        return 73
606	    }
607	
608	    var errors: [CompareError] = []
609	    let files = enumerateRegularFiles(root: sourceRoot, errors: &errors)
610	
611	    var records: [FileRecord] = []
612	    for relative in files.sorted(by: utf8Precedes) {
613	        switch hashFile(root: sourceRoot, relativePath: relative) {
614	        case .success(let record): records.append(record)
615	        case .failure(let error): errors.append(error)
616	        }
617	    }
618	
619	    guard errors.isEmpty else {
620	        reportCollectionErrors(errors)
621	        return 74
622	    }
