116	/// Writes `bytes` to a staging file inside `stagingDir` and publishes it with
117	/// `link(2)`, which fails with EEXIST instead of ever overwriting an existing
118	/// destination — so concurrent publishers of the same key let exactly one
119	/// value win. The staging file is removed on every failure path.
120	private func stageAndPublish(
121	    bytes: Data, to finalPath: String, stagingDir: String, prefix: String
122	) throws -> PublishResult {
123	    let tempName = String(
124	        format: "%@%d.%016llx.tmp",
125	        prefix,
126	        ProcessInfo.processInfo.processIdentifier,
127	        UInt64.random(in: 0...UInt64.max))
128	    let tempPath = (stagingDir as NSString).appendingPathComponent(tempName)
129	
130	    let fd = open(tempPath, O_CREAT | O_EXCL | O_WRONLY, 0o644)
131	    guard fd >= 0 else {
132	        throw HistoryError.io(
133	            "cannot create staging file: \(String(cString: strerror(errno)))")
134	    }
135	
136	    do {
137	        var offset = 0
138	        while offset < bytes.count {
139	            let written = bytes.withUnsafeBytes { rawBuffer -> Int in
140	                write(fd, rawBuffer.baseAddress!.advanced(by: offset), bytes.count - offset)
141	            }
142	            if written < 0 {
143	                if errno == EINTR { continue }
144	                throw HistoryError.io(
145	                    "staging write failed: \(String(cString: strerror(errno)))")
146	            }
147	            offset += written
148	        }
149	        if fsync(fd) != 0 {
150	            throw HistoryError.io(
151	                "staging sync failed: \(String(cString: strerror(errno)))")
152	        }
153	        if close(fd) != 0 {
154	            throw HistoryError.io(
155	                "staging close failed: \(String(cString: strerror(errno)))")
156	        }
157	    } catch {
158	        close(fd)
159	        unlink(tempPath)
160	        throw error
161	    }
162	
163	    if link(tempPath, finalPath) != 0 {
164	        let linkError = errno
165	        unlink(tempPath)
166	        if linkError == EEXIST { return .alreadyExists }
167	        throw HistoryError.io(
168	            "cannot publish \(finalPath): \(String(cString: strerror(linkError)))")
169	    }
170	    unlink(tempPath)
171	    return .published
172	}
